CREATE TABLE IF NOT EXISTS schools(id serial PRIMARY KEY,name text UNIQUE NOT NULL,campus text NOT NULL,curriculum text NOT NULL);
CREATE TABLE IF NOT EXISTS employees(id serial PRIMARY KEY,staff_id text UNIQUE NOT NULL,name text NOT NULL,email text UNIQUE NOT NULL,title text NOT NULL,department text NOT NULL,school_id integer REFERENCES schools(id),status text NOT NULL DEFAULT 'Active',start_date date NOT NULL DEFAULT CURRENT_DATE,curriculum text NOT NULL DEFAULT 'CBE');
CREATE TABLE IF NOT EXISTS users(id serial PRIMARY KEY,email text UNIQUE NOT NULL,password_hash text NOT NULL,name text NOT NULL,role text NOT NULL,school_id integer REFERENCES schools(id),employee_id integer REFERENCES employees(id),active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS sessions(token_hash text PRIMARY KEY,user_id integer REFERENCES users(id),expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS leave_requests(id serial PRIMARY KEY,employee_id integer NOT NULL REFERENCES employees(id),type text NOT NULL,start_date date NOT NULL,end_date date NOT NULL,days integer NOT NULL CHECK(days>0),reason text NOT NULL,status text NOT NULL DEFAULT 'Pending',decided_by integer REFERENCES users(id),created_at timestamptz DEFAULT now(),CHECK(end_date>=start_date));
CREATE TABLE IF NOT EXISTS records(id serial PRIMARY KEY,module text NOT NULL,title text NOT NULL,employee_id integer REFERENCES employees(id),school_id integer REFERENCES schools(id),status text NOT NULL DEFAULT 'Open',due_date date,details text NOT NULL DEFAULT '',created_by integer REFERENCES users(id),created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS audit(id bigserial PRIMARY KEY,user_id integer REFERENCES users(id),action text NOT NULL,entity text NOT NULL,created_at timestamptz DEFAULT now());
CREATE INDEX IF NOT EXISTS employee_school_idx ON employees(school_id);
CREATE INDEX IF NOT EXISTS record_school_module_idx ON records(school_id,module);
ALTER TABLE employees ADD COLUMN IF NOT EXISTS phone text NOT NULL DEFAULT '';
ALTER TABLE employees ADD COLUMN IF NOT EXISTS location text NOT NULL DEFAULT '';
ALTER TABLE employees ADD COLUMN IF NOT EXISTS employment_type text NOT NULL DEFAULT 'Permanent';
ALTER TABLE employees ADD COLUMN IF NOT EXISTS manager text NOT NULL DEFAULT '';
ALTER TABLE employees ADD COLUMN IF NOT EXISTS emergency_name text NOT NULL DEFAULT '';
ALTER TABLE employees ADD COLUMN IF NOT EXISTS emergency_phone text NOT NULL DEFAULT '';
ALTER TABLE employees ADD COLUMN IF NOT EXISTS tsc_number text NOT NULL DEFAULT '';
ALTER TABLE employees ADD COLUMN IF NOT EXISTS bio text NOT NULL DEFAULT '';
ALTER TABLE employees ADD COLUMN IF NOT EXISTS contract_end date;
ALTER TABLE employees ADD COLUMN IF NOT EXISTS details_initialized boolean NOT NULL DEFAULT false;
CREATE TABLE IF NOT EXISTS qualifications(id serial PRIMARY KEY,employee_id integer NOT NULL REFERENCES employees(id),title text NOT NULL,issuer text NOT NULL,category text NOT NULL,awarded_on date NOT NULL,expires_on date,verified boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(employee_id,title,issuer),CHECK(expires_on IS NULL OR expires_on>=awarded_on));
CREATE TABLE IF NOT EXISTS attendance_devices(id serial PRIMARY KEY,name text NOT NULL,school_id integer NOT NULL REFERENCES schools(id),kind text NOT NULL,token_hash text UNIQUE NOT NULL,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS device_enrollments(device_id integer NOT NULL REFERENCES attendance_devices(id),external_ref text NOT NULL,employee_id integer NOT NULL REFERENCES employees(id),PRIMARY KEY(device_id,external_ref),UNIQUE(device_id,employee_id));
CREATE TABLE IF NOT EXISTS attendance_events(id bigserial PRIMARY KEY,employee_id integer NOT NULL REFERENCES employees(id),direction text NOT NULL CHECK(direction IN ('IN','OUT')),occurred_at timestamptz NOT NULL,source text NOT NULL,reason text NOT NULL DEFAULT '',device_id integer REFERENCES attendance_devices(id),event_ref text UNIQUE NOT NULL,created_by integer REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS attendance_employee_time_idx ON attendance_events(employee_id,occurred_at DESC,id DESC);
CREATE INDEX IF NOT EXISTS qualification_employee_idx ON qualifications(employee_id);
ALTER TABLE employees ADD COLUMN IF NOT EXISTS org_scope text NOT NULL DEFAULT 'School';
ALTER TABLE employees ADD COLUMN IF NOT EXISTS staff_category text NOT NULL DEFAULT 'Unassigned';
UPDATE employees SET staff_category=CASE WHEN department='Academics' THEN 'Teaching' WHEN department='Leadership' THEN 'Leadership' ELSE 'Support' END WHERE staff_category='Unassigned';
CREATE TABLE IF NOT EXISTS employee_health(employee_id integer PRIMARY KEY REFERENCES employees(id),payload text NOT NULL,version integer NOT NULL DEFAULT 1,updated_by integer REFERENCES users(id),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS hub_records(id serial PRIMARY KEY,category text NOT NULL,title text NOT NULL,body text NOT NULL,school_id integer REFERENCES schools(id),classification text NOT NULL DEFAULT 'Confidential',state text NOT NULL DEFAULT 'Draft',version integer NOT NULL DEFAULT 1,due_on date,starts_at timestamptz,venue text NOT NULL DEFAULT '',owner text NOT NULL DEFAULT '',workflow_state text NOT NULL DEFAULT 'Open',created_by integer REFERENCES users(id),published_by integer REFERENCES users(id),published_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS hub_acknowledgements(record_id integer REFERENCES hub_records(id),user_id integer REFERENCES users(id),version integer NOT NULL,acknowledged_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(record_id,user_id,version));
CREATE INDEX IF NOT EXISTS hub_school_state_idx ON hub_records(school_id,state);
ALTER TABLE hub_records ADD COLUMN IF NOT EXISTS seed_key text;
CREATE UNIQUE INDEX IF NOT EXISTS hub_seed_idx ON hub_records(seed_key) WHERE seed_key IS NOT NULL;
